import { translations } from "./translations.js";

document.addEventListener("DOMContentLoaded", () => {

    const themeBtn = document.getElementById('theme-btn');
    const themeBtnMobile = document.getElementById('theme-btn-mobile');
// theme
    function toggleTheme() {
        document.body.classList.toggle('dark-mode');
        const dark = document.body.classList.contains('dark-mode');
        if (themeBtn) themeBtn.textContent = dark ? '☀️' : '🌙';
        if (themeBtnMobile) themeBtnMobile.textContent = dark ? '☀️' : '🌙';
        localStorage.setItem('theme', dark ? 'dark' : 'light');
    }

    if (themeBtn) themeBtn.addEventListener('click', toggleTheme);
    if (themeBtnMobile) themeBtnMobile.addEventListener('click', toggleTheme);

    if (localStorage.getItem('theme') === 'dark') {
        document.body.classList.add('dark-mode');
        if (themeBtn) themeBtn.textContent = '☀️';
        if (themeBtnMobile) themeBtnMobile.textContent = '☀️';
    }

// language
    const langSelect = document.getElementById('lang-select');
    const langSelectMobile = document.getElementById('lang-select-mobile');

    function changeLanguage(lang) {
        if (!translations[lang]) return;

        document.querySelectorAll('[data-i18n]').forEach(el => {
            const key = el.getAttribute('data-i18n');
            if (translations[lang][key]) el.textContent = translations[lang][key];
        
        const searchInput = document.getElementById('project-search');
        if (searchInput) searchInput.placeholder = translations[lang].search_placeholder;
    });

    localStorage.setItem('lang', lang);
}

    if (langSelect) langSelect.addEventListener('change', e => changeLanguage(e.target.value));
    if (langSelectMobile) langSelectMobile.addEventListener('change', e => changeLanguage(e.target.value));

    const savedLang = localStorage.getItem('lang') || 'fr';
    changeLanguage(savedLang);
    if (langSelect) langSelect.value = savedLang;
    if (langSelectMobile) langSelectMobile.value = savedLang;

// menu toogle
    const menuIcon = document.querySelector(".hamburger-icon");
    if (menuIcon) {
        menuIcon.addEventListener('click', () => {
            document.querySelector(".menu-links")?.classList.toggle("open");
            menuIcon.classList.toggle("open");
        });
    }

// caroussel
    const images = document.querySelectorAll('.carousel img');
    if (images.length > 0) {
        let current = 0;
        const nextBtn = document.getElementById('next');
        const prevBtn = document.getElementById('prev');

        function showImage(index) {
            images.forEach(img => img.classList.remove('active'));
            images[index].classList.add('active');
        }

        if (nextBtn) {
            nextBtn.addEventListener('click', () => {
                current = (current + 1) % images.length;
                showImage(current);
            });
        }

        if (prevBtn) {
            prevBtn.addEventListener('click', () => {
                current = (current - 1 + images.length) % images.length;
                showImage(current);
            });
        }
    }

// Search filter
// project filter
const searchInput = document.getElementById('project-search');
const filterTags = document.querySelectorAll('.filter-tag');
const projectCards = document.querySelectorAll('#projects-grid .details-container');

function filterProjects() {
    const query = searchInput?.value.toLowerCase() || '';
    const activeTag = document.querySelector('.filter-tag.active')?.dataset.filter || 'all';

    projectCards.forEach(card => {
        const tags = card.dataset.tags?.toLowerCase() || '';
        const title = card.querySelector('.project-title')?.textContent.toLowerCase() || '';

        const matchesSearch = query === '' || title.includes(query) || tags.includes(query);
        const matchesTag = activeTag === 'all' || tags.includes(activeTag.toLowerCase());

        card.classList.toggle('hidden', !(matchesSearch && matchesTag));
    });
}

filterTags.forEach(btn => {
    btn.addEventListener('click', () => {
        filterTags.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        filterProjects();
    });
});

searchInput?.addEventListener('input', filterProjects);

});
